class Solution {
public:
    int surfaceArea(vector<vector<int>>& grid) {
        int n = grid.size();
        int total = 0;
        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j];
                if (v > 0) total += 2;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d];
                    int nj = j + dc[d];
                    int nv = 0;
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                        nv = grid[ni][nj];
                    }
                    total += (v > nv) ? (v - nv) : 0;
                }
            }
        }
        return total;
    }
};
